lo.com","investor":"CVC Asia Fund VI","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":["Peak XV","Antler Elevate"],"seller":null,"round":"growth","stake_pct":null,"amount":220000000.0,"currency":"USD","amount_basis":"round_size","valuation":1000000000.0,"valuation_currency":"USD","headline":"Airalo becomes the first eSIM Unicorn with an investment round of $220m","summary":"eSIM provider Airalo raised $220m led by CVC Asia Fund VI ($185m) with Peak XV and Antler Elevate, at a valuation above $1bn.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/media/news/2025/airalo-becomes-the-first-esim-unicorn-with-an-investment-round-of-220m/","evidence":"Airalo, the world’s first and largest eSIM provider, today announced a $220m investment led by new investor, CVC.","verified":true},{"key":"pr:df1ebf2fe2e19d87d80eb417463009bf","date":"2025-07-21","date_text":null,"kind":"minority_investment","asset_class":"private_equity","target":"Etraveli Group","portco_name":"Etraveli Group","target_website":"etraveligroup.com","investor":"KKR","sponsor_is_investor":false,"sponsor_role":null,"co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"CVC welcomes strategic minority partnership investment from KKR into Etraveli Group","summary":"KKR agreed to acquire a significant minority stake in CVC-backed travel technology company Etraveli Group; terms undisclosed.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/media/news/2025/cvc-welcomes-strategic-minority-partnership-investment-from-kkr-into-etraveli-group/","evidence":"CVC Capital Partners (“CVC”) today announced that KKR has agreed to acquire a significant minority stake in global travel technology company Etraveli Group.","verified":null},{"key":"pr:d736a807bae0e6807b6f19b4325c70be","date":"2025-08-01","date_text":null,"kind":"minority_investment","asset_cla