ite Mountains to sell Bamboo to CVC","summary":"White Mountains agreed to sell a controlling interest in insurance distributor Bamboo to CVC-advised funds at a $1.75bn valuation, keeping about 15%.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/media/news/2025/white-mountains-to-sell-bamboo-to-cvc/","evidence":"The transaction values Bamboo at $1.75 billion.","verified":true},{"key":"pr:40a25f219fe0b90ac7859c84972830ff","date":"2025-10-03","date_text":null,"kind":"minority_investment","asset_class":"private_equity","target":"International Schools Partnership","portco_name":"International Schools Partnership","target_website":"internationalschoolspartnership.com","investor":"CVC Strategic Opportunities","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":"Partners Group","round":null,"stake_pct":20.0,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Partners Group and CVC agree partnership to drive next phase of growth at International Schools Partnership, a leading global K-12 school platform","summary":"CVC Strategic Opportunities agreed to acquire a 20% stake in K-12 school group ISP, with Partners Group remaining majority owner.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/media/news/2025/partners-group-and-cvc-agree-partnership-to-drive-next-phase-of-growth-at-international-schools-partnership-a-leading-global-k-12-school-platform/","evidence":"CVC will acquire a 20% stake in the Company.","verified":null},{"key":"pr:52e075df283c3ee89cc028981296fa90","date":"2025-10-16","date_text":null,"kind":"minority_investment","asset_class":"private_equity","target":"Sebia","portco_name":"Sebia","target_website":"sebia.com","investor":"Warburg Pincus","sponsor_is_investor":false,"sponsor_role":null,"co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_curre