is/","evidence":"PETERSBURG, FL, USA – The WTA (Women’s Tennis Association) announced today that they have entered into a strategic partnership indirectly with funds managed by CVC Capital Partners (“CVC”).","verified":null},{"key":"pr:e048687e6e993935bb0a71608652fd52","date":"2023-03-15","date_text":null,"kind":"minority_investment","asset_class":"private_equity","target":"PT Samator Indo Gas","portco_name":"PT Samator Indo Gas","target_website":"samatorgas.com","investor":"CVC Asia V","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":155000000.0,"currency":"USD","amount_basis":"stake_price","valuation":null,"valuation_currency":null,"headline":"CVC Asia V invests in Samator Indo Gas, Indonesia’s leading industrial and medical gas company","summary":"A CVC Funds-backed holding company acquired a significant minority stake in Indonesian gas company Samator Indo Gas from existing shareholders for about US$155m.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/media/news/2023/2023-03-15-cvc-asia-v-invests-in-samator-indo-gas-indonesia-s-leading-industrial-and-medical-gas-company/","evidence":"PT Samator Indo Gas Tbk. (the “Company” or “Samator Indo Gas”) (Bloomberg Code: AGII IJ) (previously PT Aneka Gas Industri Tbk) announced today that Matrix Company Limited, an investment holding company invested in by funds (“CVC Funds”) advised and/or managed by CVC Capital Partners (“CVC”), has acquired a significant minority stake in the Company from existing shareholders for approximately US$155 million.","verified":true},{"key":"pr:d803f5c269800119458566a0d8c0b0e7","date":"2023-04-11","date_text":null,"kind":"debt_financing","asset_class":"private_equity","target":"APRIL Group","portco_name":"APRIL Group","target_website":null,"investor":"CVC Credit","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":null,"c