ion","asset_class":"private_equity","target":"DIF Capital Partners","portco_name":"DIF Capital Partners","target_website":null,"investor":"CVC","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"CVC acquires leading infrastructure manager DIF","summary":"CVC agreed to acquire a majority stake in infrastructure manager DIF Capital Partners, with a commitment to acquire the remaining shares over time.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/media/news/2023/2023-09-05-cvc-acquires-leading-infrastructure-manager-dif/","evidence":"CVC, a leading global private markets manager focused on private equity, secondaries and credit is acquiring a majority stake in leading infrastructure manager, DIF Capital Partners (“DIF”), and providing a commitment to acquire the remaining shares over time.","verified":null},{"key":"pr:23366553b8b14ca213aa759abf90be08","date":"2023-09-18","date_text":null,"kind":"company_acquisition","asset_class":"private_equity","target":"Dale Underwriting Partners","portco_name":"Dale Underwriting Partners","target_website":"daleuw.com","investor":"CVC funds","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Dale Underwriting Partners enters strategic partnership with CVC to support long-term growth","summary":"CVC funds agreed to invest in Lloyd's Syndicate 1729 manager Dale Underwriting Partners, replacing third-party capital and taking a majority stake.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/media/news/2023/2023-09-18-dale-underwriting-partners-enters-strategic-partnership-with-cvc-to-support-long-term-growth/","evidence":"CVC funds will invest into Dale t