:null},{"key":"pr:cf0562f3e666aefac4e19de76bf1059c","date":"2018-11-05","date_text":null,"kind":"debt_financing","asset_class":"private_equity","target":"Industrial Physics","portco_name":null,"target_website":null,"investor":"CVC Credit Partners","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"CVC Credit Partners provides financing to support Industrial Physics, Inc.","summary":"CVC Credit Partners acted as administrative agent on a first lien facility for Union Park-formed Industrial Physics to fund an acquisition and refinance.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/media/news/2018/2018-11-05-cvc-credit-partners-provides-financing-to-support-industrial-physics-inc/","evidence":"CVC Credit Partners announced today that it acted as Administrative Agent on a first lien senior secured credit facility provided to Industrial Physics, Inc (\"Industrial Physics\").","verified":null},{"key":"pr:9900f0191184bbb0d9802a8a793827bd","date":"2018-11-06","date_text":null,"kind":"company_acquisition","asset_class":"private_equity","target":"ConvergeOne","portco_name":"ConvergeOne","target_website":"onec1.com","investor":"CVC Fund VII","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":"Clearlake Capital and public shareholders","round":null,"stake_pct":null,"amount":1800000000.0,"currency":"USD","amount_basis":"enterprise_value","valuation":null,"valuation_currency":null,"headline":"ConvergeOne agrees to be acquired by CVC Fund VII for $1.8 billion","summary":"ConvergeOne agreed to be acquired by CVC Fund VII affiliates via a $12.50 per share tender offer in an all-cash deal valued at about $1.8bn.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/media/news/2018/2018-11-06-convergeone-agrees-to-be-acquired-by-cvc-fund-vii-for-1