-partners-sells-starbev-to-molson-coors-brewing-company/","evidence":"CVC Capital Partners today announced that Molson Coors Brewing Company (NYSE: TAP; TSX) has signed a definitive agreement with StarBev L.P., owned by funds advised by CVC Capital Partners Limited (\"CVC\") and StarBev management, to acquire StarBev for €2.65 billion ($3.54 billion).","verified":true},{"key":"pr:8544047bdedd9cbf3ec1833f7b9074cf","date":"2012-04-11","date_text":null,"kind":"company_acquisition","asset_class":"private_equity","target":"Hong Kong Broadband Network (HKBN)","portco_name":"Hong Kong Broadband Network (HKBN)","target_website":null,"investor":"CVC Capital Partners","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":"City Telecom Inc.","round":null,"stake_pct":null,"amount":5000000000.0,"currency":"HKD","amount_basis":"enterprise_value","valuation":null,"valuation_currency":null,"headline":"CVC Capital Partners announces agrees acquisition of Hong Kong Broadband Network","summary":"A CVC Funds company agreed to acquire Hong Kong Broadband Network and IDD businesses from City Telecom for a transaction value of about HK$5bn.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/media/news/2012/2012-04-11-cvc-capital-partners-announces-agrees-acquisition-of-hong-kong-broadband-network/","evidence":"The transaction value is approximately HK$5 billion, to be funded by a combination of equity and debt financing.","verified":true},{"key":"pr:aee3de3545f136531340dfd70c2385cc","date":"2012-04-13","date_text":null,"kind":"minority_investment","asset_class":"private_equity","target":"Venturepharma Group","portco_name":"Venturepharma Group","target_website":null,"investor":"CVC Asia Pacific","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"CVC announces investment in Vent