arters to tier-one European energy companies.","verified":null},{"key":"pr:c64dd4bda295ead4d0e0fd8fd6aba52d","date":"2025-06-25","date_text":null,"kind":"company_acquisition","asset_class":"private_equity","target":"OMR Moerdijk","portco_name":"OMR Moerdijk","target_website":null,"investor":"CVC DIF (Dutch Infrastructure Opportunities Fund)","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":"Perpetual Next Conversions","round":null,"stake_pct":100.0,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"CVC DIF aquires Dutch food waste and anaerobic digestion business","summary":"A CVC DIF-managed Dutch fund agreed to acquire 100% of food waste anaerobic digestion business OMR Moerdijk from Perpetual Next Conversions.","source_name":"CVC DIF","source_url":"https://www.cvcdif.com/news-insights/cvc-dif-aquires-dutch-food-waste-and-anaerobic-digestion-business","evidence":"CVC DIF, the infrastructure strategy of leading global private markets manager CVC, is pleased to announce that the Dutch Infrastructure Opportunities Fund managed by CVC DIF will acquire 100% of OMR Moerdijk B.V. (“OMR”) from Perpetual Next Conversions.","verified":null},{"key":"pr:0ff1cbed438d02924db47a7ef284a4f2","date":"2025-04-16","date_text":null,"kind":"add_on_acquisition","asset_class":"private_equity","target":"Beaverbank Place and Firhill Court","portco_name":null,"target_website":null,"investor":"Ottoway Portfolio Holdings","sponsor_is_investor":false,"sponsor_role":"co_investor","co_investors":["CVC DIF"],"seller":"Mapletree Global Student Accommodation Private Trust","round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"CVC DIF’s Ottoway acquires two UK student accommodation assets","summary":"CVC DIF's Ottoway acquired two Scottish purpose-built student accommodation assets from Mapletree, adding 750 beds.","source_name":"CVC DIF","source_url":"https://www.cvcdif.com/news-insights/cvc-dif-s-ottoway-acquires-two-uk-student-accommodation-assets","evidence":"CVC DIF, the infrastructure strategy of leading global private markets manager CVC, is pleased to announce the strategic acquisition for its student accommodation platform, Ottoway Portfolio Holdings (“Ottoway”), of two purpose-built student accommodation assets from Mapletree Global Student Accommodation Private Trust.","verified":null},{"key":"pr:0711914cb7f275bdfb4ba0ec78c814a6","date":"2023-06-15","date_text":null,"kind":"debt_financing","asset_class":"private_equity","target":"UK co-location solar and battery portfolio (Verdant)","portco_name":null,"target_website":null,"investor":"ABN AMRO","sponsor_is_investor":false,"sponsor_role":null,"co_investors":["ING","Rabobank","NAB","KFW","Lloyds"],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"DIF Capital Partners achieves financial close on 540MW co-location solar and battery portfolio","summary":"DIF reached financial close on senior debt and an equity bridge loan from a bank club for the first 540MW of its UK co-located solar and battery portfolio, owned with ib vogt.","source_name":"CVC DIF","source_url":"https://www.cvcdif.com/news-insights/dif-capital-partners-achieves-financial-close-on-540mw-co-location-solar-and-battery-portfolio","evidence":"It also includes an equity bridge loan provided by a club of senior lenders comprising ABN AMRO, ING, Rabobank, NAB, KFW and Lloyds, with Lloyds acting as agent.","verified":null},{"key":"pr:1ffad9ced13ec32745c5623d26cde442","date":"2023-11-20","date_text":null,"kind":"debt_financing","asset_class":"private_equity","target":"Bay Village Karratha Accommodation Facility","portco_name":"Bay Village Karratha Accommodation Facility","target_website":null,"investor":"MUFG","sponsor_is_investor":false,"sponsor_role":null,"co_investors":[],"seller":