null,"stake_pct":null,"amount":208000000.0,"currency":"EUR","amount_basis":"debt","valuation":null,"valuation_currency":null,"headline":"DIF high speed fibre portfolio company ielo closes EUR 208 million senior debt financing","summary":"DIF portfolio company ielo closed a EUR 208m senior debt financing from a lender club to refinance and fund growth.","source_name":"CVC DIF","source_url":"https://www.cvcdif.com/news-insights/dif-high-speed-fibre-portfolio-company-ielo-closes-eur-208-million-senior-debt-financing","evidence":"DIF Capital Partners (via its CIF II fund) and ielo’s founding shareholders are pleased to announce that DIF portfolio company ielo, a leading French high speed fibre provider, has closed a EUR 208 million senior debt financing to refinance its existing debt and support its growth ambitions.","verified":true},{"key":"pr:ad34b812961f4b8031f4c2e5a816e4ec","date":"2023-11-30","date_text":null,"kind":"add_on_acquisition","asset_class":"private_equity","target":"EdgeX Data Centers","portco_name":null,"target_website":null,"investor":"Tonaquint Data Centers","sponsor_is_investor":false,"sponsor_role":null,"co_investors":["DIF Capital Partners"],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"DIF investee company Tonaquint acquires EdgeX Data Centers in Oklahoma City","summary":"DIF investee Tonaquint acquired EdgeX Data Centers in Oklahoma City.","source_name":"CVC DIF","source_url":"https://www.cvcdif.com/news-insights/dif-investee-company-tonaquint-acquires-edgex-data-centers-in-oklahoma-city","evidence":"DIF Capital Partners’ (DIF) investee company Tonaquint Data Centers (Tonaquint) has acquired EdgeX Data Centers (EdgeX), adding a further site to its portfolio of data centres in the United States.","verified":null},{"key":"pr:69a3fb61088f1b7144ef74198ac7d16c","date":"2023-08-14","date_text":null,"kind":"debt_financing","asset_class":"private_equity","target":"metrofibre (ruhrfibre)","portco_name":"metrofibre","target_website":null,"investor":"ING","sponsor_is_investor":false,"sponsor_role":null,"co_investors":["Kommunalkredit Austria","SEB"],"seller":null,"round":null,"stake_pct":null,"amount":120000000.0,"currency":"EUR","amount_basis":"debt","valuation":null,"valuation_currency":null,"headline":"DIF’s portfolio company ruhrfibre signs EUR 120m senior debt financing","summary":"DIF portfolio company ruhrfibre, developed with metrofibre and the City of Essen, closed EUR 120m of green senior loans.","source_name":"CVC DIF","source_url":"https://www.cvcdif.com/news-insights/dif-s-portfolio-company-ruhrfibre-signs-eur-120m-senior-debt-financing","evidence":"The financing package comprises senior loans totalling EUR 120m that are provided by a club of senior lenders comprising ING, Kommunalkredit Austria and SEB.","verified":true},{"key":"pr:299aa038e9c54ad6efde3e5a8d18027e","date":"2025-05-21","date_text":null,"kind":"other","asset_class":"private_equity","target":"Diverso Energy","portco_name":"Diverso Energy","target_website":null,"investor":"Diverso Energy","sponsor_is_investor":false,"sponsor_role":null,"co_investors":["Mattamy Homes"],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Diverso Energy forms strategic partnership with Mattamy Homes","summary":"CVC DIF's Diverso Energy formed a strategic geoexchange partnership with homebuilder Mattamy Homes.","source_name":"CVC DIF","source_url":"https://www.cvcdif.com/news-insights/diverso-energy-forms-strategic-partnership-with-mattamy-homes","evidence":"CVC DIF, the infrastructure strategy of leading global private markets manager CVC, is pleased to announce the formation of a strategic partnership between its ground source heating and cooling (“geoexchange”) platform Diverso Energy (“Diverso”), the leading geoexchange utility in North America, and Mattamy Homes (“Mattamy”), one of the largest privately owned homebuilders in North America and an industry leader in sustainable low-carbon homebuilding.","verified":null},{"key":"pr:f0ad947aa200dad8e471d5e22df02e85","date":null,"date_text":null,"kind":"company_acquisition","asset_class":"private_equity","target":"Good Choice","portco_name":"Good Choice","target_website":"gccompany.co.kr","investor":"CVC Capital Partners","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":80.0,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Good Choice | CVC","summary":"CVC acquired an 80% stake in Korean online accommodation booking service Good Choice.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/portfolio/case-studies/good-choice/","evidence":"Since CVC acquired an 80% stake in Good Choice, the business has invested in improving salesforce productivity, reinforcing its IT infrastructure and leveraging data-driven analysis to identify new growth and revenue opportunities.","verified":null},{"key":"pr:d518dc5382b2545a85656f74d48add00","date":null,"date_text":null,"kind":"company_acquisition","asset_class":"private_equity","target":"WithSecure","portco_name":"WithSecure","target_website":"withsecure.com","investor":"CVC Catalyst","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":["Risto Siilasmaa"],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"WithSecure | CVC","summary":"CVC Catalyst took Finnish cybersecurity provider WithSecure private in partnership with founder Risto Siilasmaa, who rolled 100% of his equity; its first Catalyst investment.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/portfolio/case-studies/withsecure/","evidence":"CVC proactively originated this proprietary opportunity by approaching WithSecure’s founder, Risto Siilasmaa who agreed to partner exclusively with CVC to take the business private and help accelerate the development of the company.","verified":null},{"key":"pr:bd6163bcc82744bc5d81bbd79fd5e5bd","date":null,"date_text":"2016","kind":"company_exit","asset_class":"private_equity","target":"Quirónsalud","portco_name":"Quironsalud (IDCsalud)","target_website":null,"investor":"Fresenius Helios","sponsor_is_investor":false,"sponsor_role":"seller","co_investors":[],"seller":"CVC","round":null,"stake_pct":null,"amount":5800000000.0,"currency":"EUR","amount_basis":"unspecified","valuation":null,"valuation_currency":null,"headline":"Quirónsalud | CVC","summary":"CVC sold Spanish hospital group Quirónsalud to Fresenius Helios in 2016 for €5.8bn.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/portfolio/case-studies/quironsalud/","evidence":"In 2016, CVC found such a partner in Fresenius Helios, the global healthcare group, which acquired Quirónsalud for €5.8 billion, creating a European leader in hospital management.","verified":true},{"key":"pr:eabb02025dfbb4739e38b38ebbcb3751","date":null,"date_text":"early 2006","kind":"company_acquisition","asset_class":"private_equity","target":"Formula One","portco_name":"Formula One","target_website":null,"investor":"CVC Funds","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":"a group of shareholders including the lenders to Kirch Media","round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Formula One | CVC","summary":"CVC Funds acquired a majority share in Formula One in early 2006 from shareholders including the lenders to Kirch Media.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/portfolio/case-studies/formula-one/","evidence":"In early 2006, following a lengthy period of due diligence and negotiation, CVC Funds successfully acquired a majority share in Formula One from a disparate group of shareholders, including the lenders to Kirch Media.","verified":null},{"key":"pr:4539277f93c0a854e1eb0640c265df85","date":null,"date_text":"April 2024","kind":"company_acquisition","asset_class":"private_equity","target":"Sunday Natural","portco_name":"Sunday Natural","target_website":"sunday.de","investor":"CVC Funds","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":55.0,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Sunday Natural | CVC","summary":"CVC completed its investment in Sunday Natural in April 2024, acquiring about 55% with the founder keeping the rest.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/portfolio/case-studies/sunday-natural/","evidence":"CVC’s investment was completed in April 2024, with the firm acquiring a stake of approximately 55%, with the founder retaining the remainder.","verified":null},{"key":"pr:bf407ddfdf6721137405baaf1cac374d","date":null,"date_text":"2021","kind":"company_acquisition","asset_class":"private_equity","target":"Gujarat Titans","portco_name":"Gujarat Titans","target_website":"gujarattitansipl.com","investor":"CVC","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Gujarat Titans | CVC","summary":"CVC won the 2021 IPL tender for the right to own and operate the new Ahmedabad franchise, Gujarat Titans.","source_name":"CVC Capital Partners","source_url":"https://www.cvc.com/portfolio/case-studies/gujarat-titans/","evidence":"CVC won the right to own and operate the new franchise based in Ahmedabad in Gujarat province – in the largest cricket stadium in India, which has a capacity of 132,000.","verified":null}]}$pf$::jsonb;
  n_companies int;
  n_deals int;
begin
  select id into gp from public.companies
   where category = 'GP' and name = 'CVC Capital Partners'
   order by (source = 'master_directory') desc nulls last, created_at
   limit 1;
  if gp is null then raise exception 'sponsor % is not in the directory', 'CVC Capital Partners'; end if;

  insert into public.portfolio_companies as pc (external_key, gp_company_id, name, domain, description, sector, hq, status, invested_year, exit_year, fund_name,
      source, source_url, deal_value, deal_currency, deal_value_basis, stake_pct, co_investors, deal_source_url, researched_at)
  select gp::text || ':' || (c->>'slug'), gp, c->>'name', c->>'domain', c->>'description', c->>'sector', c->>'hq', c->>'status',
         (c->>'invested_year')::int, (c->>'exit_year')::int, c->>'fund_name', 'web_research', c->>'source_url',
         (c->>'deal_value')::numeric, c->>'deal_currency', c->>'deal_value_basis', (c->>'stake_pct')::numeric,
         coalesce(array(select jsonb_array_elements_text(c->'co_investors')), '{}'), c->>'deal_source_url', now()
    from jsonb_array_elements(doc->'companies') c
  on conflict (external_key) do update set
    name = case when pc.source = 'manual' then pc.name else excluded.name end,
    domain = coalesce(pc.domain, excluded.domain),
    description = case when pc.source = 'manual' then coalesce(pc.description, excluded.description) else coalesce(excluded.description, pc.description) end,
    sector = case when pc.source = 'manual' then coalesce(pc.sector, excluded.sector) else coalesce(excluded.sector, pc.sector) end,
    hq = case when pc.source = 'manual' then coalesce(pc.hq, excluded.hq) else coalesce(excluded.hq, pc.hq) end,
    status = coalesce(excluded.status, pc.status),
    invested_year = coalesce(excluded.invested_year, pc.invested_year),
    exit_year = coalesce(excluded.exit_year, pc.exit_year),
    fund_name = coalesce(excluded.fund_name, pc.fund_name),
    source_url = case when pc.source = 'manual' then coalesce(pc.source_url, excluded.source_url) else excluded.source_url end,
    deal_value = coalesce(excluded.deal_value, pc.deal_value),
    deal_currency = case when excluded.deal_value is not null then excluded.deal_currency else pc.deal_currency end,
    deal_value_basis = case when excluded.deal_value is not null then excluded.deal_value_basis else pc.deal_value_basis end,
    stake_pct = coalesce(excluded.stake_pct, pc.stake_pct),
    co_investors = case when cardinality(excluded.co_investors) > 0 then excluded.co_investors else pc.co_investors end,
    deal_source_url = coalesce(excluded.deal_source_url, pc.deal_source_url),
    researched_at = now();
  get diagnostics n_companies = row_count;

  insert into public.deals as d (external_key, date, date_text, kind, asset_class, target, target_kind, target_key, target_website, investor, investor_company_id,
      co_investors, seller, round, stake_pct, amount, currency, amount_basis, valuation, valuation_currency, headline, summary, source_name, source_url,
      evidence, verified, source)
  select x->>'key', (x->>'date')::date, x->>'date_text', x->>'kind', x->>'asset_class', x->>'target', 'company',
         public.borrower_key(coalesce(x->>'portco_name', x->>'target')), x->>'target_website', x->>'investor',
         case when (x->>'sponsor_is_investor')::boolean then gp else (select m.company_id from ingest.match_firm(x->>'investor', array['GP']) m) end,
         coalesce(array(select jsonb_array_elements_text(x->'co_investors')), '{}'), x->>'seller', x->>'round', (x->>'stake_pct')::numeric,
         (x->>'amount')::numeric, x->>'currency', x->>'amount_basis', (x->>'valuation')::numeric, x->>'valuation_currency',
         x->>'headline', x->>'summary', x->>'source_name', x->>'source_url', x->>'evidence', (x->>'verified')::boolean, 'web_research'
    from jsonb_array_elements(doc->'deals') x
  on conflict (external_key) do update set
    date = excluded.date, date_text = excluded.date_text, kind = excluded.kind, target = excluded.target, target_key = excluded.target_key,
    target_website = coalesce(excluded.target_website, d.target_website), investor = excluded.investor,
    investor_company_id = coalesce(excluded.investor_company_id, d.investor_company_id),
    co_investors = (select coalesce(array_agg(distinct v), '{}') from unnest(d.co_investors || excluded.co_investors) v),
    seller = coalesce(excluded.seller, d.seller), round = coalesce(excluded.round, d.round), stake_pct = coalesce(excluded.stake_pct, d.stake_pct),
    amount = excluded.amount, currency = excluded.currency, amount_basis = excluded.amount_basis,
    valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, headline = excluded.headline,
    summary = coalesce(excluded.summary, d.summary), source_name = excluded.source_name, source_url = excluded.source_url,
    evidence = excluded.evidence, verified = coalesce(excluded.verified, d.verified);
  get diagnostics n_deals = row_count;

  update public.companies set portfolio_note = 'cvc.com/portfolio/our-portfolio/ via its Umbraco endpoints /umbraco/surface/locationitems/PortfolioLocationItems (pages 1-9) and PortfolioItemPopup (160 current companies: year, strategy, country, industry, website); CVC DIF infrastructure portfolio via the cvcdif.com/infrastructure/investments server action (30); realized and other holdings from every cvc.com news release and case study in /xmlsi', portfolio_researched_at = now() where id = gp;
  insert into ingest.log (what, detail) values ('load_portfolio', jsonb_build_object('sponsor', 'CVC Capital Partners', 'companies', n_companies, 'deals', n_deals));
end $pfdo$;
